package za.co.gpbrij.cph.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; private String entityType; private String entityId; private String action; private String actor; @Column(length=2000) private String detail; private Instant occurredAt=Instant.now(); public String getId(){return id;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public String getEntityId(){return entityId;} public void setEntityId(String v){entityId=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getActor(){return actor;} public void setActor(String v){actor=v;} public String getDetail(){return detail;} public void setDetail(String v){detail=v;} public Instant getOccurredAt(){return occurredAt;} }
